 if(e.target.id==='addTemplateMonster'){let t=state.encounterTemplates[+e.target.dataset.index],m=allMonsters().find(x=>x.id===$('#templateMonster').value),row=t.members.find(x=>x.monsterId===m.id);if(row)row.qty+=+$('#templateQty').value||1;else t.members.push({monsterId:m.id,name:m.name,qty:+$('#templateQty').value||1});save();$('#modal').close();render()}
 if(e.target.id==='saveMonsterVariant'){let old=state.customMonsters.find(x=>x.id===e.target.dataset.id),m=old||{id:uid(),custom:true};Object.assign(m,{name:$('#monsterName').value,hp:+$('#monsterHp').value,maxHp:+$('#monsterHp').value,ac:+$('#monsterAc').value,speed:+$('#monsterSpeed').value,note:$('#monsterNote').value,custom:true});if(!old)state.customMonsters.push(m);save();$('#modal').close();render()}
 if(e.target.id==='saveSpeciesTree'){let name=$('#treeSpecies').value.trim(),subs=$('#treeSubspecies').value.split(',').map(x=>x.trim()).filter(Boolean);if(name)state.customSpecies.push({name,subs}),save(),$('#modal').close(),render()}
 if(e.target.id==='saveClassTree'){let name=$('#treeClass').value.trim(),subs=$('#treeSubclass').value.split(',').map(x=>x.trim()).filter(Boolean);if(name)state.customClasses.push({name,subs}),save(),$('#modal').close(),render()}
 if(e.target.id==='applyHp'){let c=state.characters.find(x=>x.id===e.target.dataset.id);c.hp=Math.max(0,Math.min(c.maxHp,c.hp+(+$('#hpAmount').value)));window.v31SyncEncounterFromCharacter?.(c,{hp:true});save();$('#modal').close();render()}
 if(e.target.id==='giveItem'){let c=state.characters.find(x=>x.id===e.target.dataset.id);c.inventory.push({id:uid(),name:$('#itemName').value,qty:+$('#itemQty').value||1,note:$('#itemNote').value,equipped:false});save();$('#modal').close();render()}
 if(e.target.id==='giveEffect'){let c=state.characters.find(x=>x.id===e.target.dataset.id),v=$('#customEffect').value||$('#effectName').value;if(v&&!c.effects.includes(v))c.effects.push(v);window.v31SyncEncounterFromCharacter?.(c,{effects:true});save();$('#modal').close();render()}
 if(e.target.id==='saveEncounter'){state.encounter.push({id:uid(),name:$('#eName').value,init:+$('#eInit').value,hp:+$('#eHp').value,ac:+$('#eAc').value,turn:!state.encounter.length});save();$('#modal').close();render()}
