function roll(sides){let count=+($('#diceCount')?.value||1),bonus=+($('#diceBonus')?.value||0),vals=Array.from({length:count},()=>1+Math.floor(Math.random()*sides)),total=vals.reduce((a,b)=>a+b,0)+bonus;let out=$('#rollout');if(out)out.innerHTML=`${total}<small>${vals.join(' + ')}${bonus?` ${bonus>0?'+':''}${bonus}`:''}</small>`;else alert('d'+sides+': '+total)}
const fold=s=>String(s).toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
async function searchGuide(){await loadGuideText();let input=$('#guideSearch'),q=input?.value.trim();if(!q||q.length<2){$('#guideResults').innerHTML='<div class="empty">En az 2 karakter yaz.</div>';return}let needle=fold(q),parts=guide.split(/\n\s*\n|(?=\n[A-ZÇĞİÖŞÜ][A-ZÇĞİÖŞÜ 0-9]{3,}\n)/),hits=parts.filter(p=>fold(p).includes(needle)).slice(0,30);if(!hits.length){let words=needle.split(/\s+/).filter(x=>x.length>2);hits=parts.filter(p=>words.every(w=>fold(p).includes(w))).slice(0,30)}let rx=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');$('#guideResults').innerHTML=hits.length?`<p class="muted"><b>${hits.length}</b> sonuç bulundu.</p>`+hits.map(h=>`<div class="guide-hit">${esc(h).replace(rx,m=>`<mark>${m}</mark>`)}</div>`).join(''):'<div class="empty">Sonuç bulunamadı. Daha kısa veya farklı bir kelime dene.</div>'}
